import { prisma } from "@/core/server/prisma";
import { PriceForm, ProductForm } from "@/modules/payments/components/CommerceAdminForms";
export default async function AdminProductsPage() { const products = await prisma.product.findMany({ include: { prices: true }, orderBy: { createdAt: "desc" } }); return <div><h1 className="text-3xl font-bold">Products and prices</h1><ProductForm /><PriceForm /><section className="mt-7 grid gap-3">{products.map((product) => <article key={product.id} className="rounded-xl border bg-white p-4"><p className="font-bold">{product.title} <span className="text-sm font-normal text-slate-500">{product.type}</span></p><p className="text-xs text-slate-500">{product.id}</p><p className="mt-2 text-sm">{product.prices.map((price) => `${price.provider} ${price.amount / 100} ${price.currency} (${price.billingPeriod})`).join(" · ") || "No active price"}</p></article>)}</section></div>; }
